-- Local source-based planning extraction. Not approved EMMA or evaluated outcomes.
CREATE TABLE research_register.plan_extraction (plan_id VARCHAR PRIMARY KEY, source_file VARCHAR NOT NULL, source_sha256 VARCHAR NOT NULL, worksheet_sha256 VARCHAR NOT NULL, record_status VARCHAR NOT NULL, normalization_note VARCHAR NOT NULL, lifecycle_note VARCHAR NOT NULL);
CREATE TABLE research_register.plan_passage (passage_id INTEGER PRIMARY KEY, plan_id VARCHAR NOT NULL REFERENCES research_register.plan_extraction(plan_id), pdf_page INTEGER NOT NULL, printed_page VARCHAR, section_label VARCHAR, UNIQUE(plan_id,pdf_page,printed_page,section_label));
CREATE TABLE research_register.plan_objective (objective_id VARCHAR PRIMARY KEY, plan_id VARCHAR NOT NULL REFERENCES research_register.plan_extraction(plan_id), objective_name VARCHAR NOT NULL, normalized_text VARCHAR NOT NULL);
CREATE TABLE research_register.plan_objective_passage (objective_id VARCHAR NOT NULL REFERENCES research_register.plan_objective(objective_id), passage_id INTEGER NOT NULL REFERENCES research_register.plan_passage(passage_id), PRIMARY KEY(objective_id,passage_id));
CREATE TABLE research_register.objective_detail_page (objective_id VARCHAR NOT NULL REFERENCES research_register.plan_objective(objective_id), pdf_page INTEGER NOT NULL, PRIMARY KEY(objective_id,pdf_page));
CREATE TABLE research_register.plan_criterion (criterion_id VARCHAR PRIMARY KEY, plan_id VARCHAR NOT NULL REFERENCES research_register.plan_extraction(plan_id), statement_kind VARCHAR NOT NULL, summary VARCHAR NOT NULL, qualification VARCHAR, scope_note VARCHAR);
CREATE TABLE research_register.plan_objective_criterion (objective_id VARCHAR NOT NULL REFERENCES research_register.plan_objective(objective_id), criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), relation_status VARCHAR NOT NULL, basis VARCHAR NOT NULL, PRIMARY KEY(objective_id,criterion_id));
CREATE TABLE research_register.plan_criterion_passage (criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), passage_id INTEGER NOT NULL REFERENCES research_register.plan_passage(passage_id), PRIMARY KEY(criterion_id,passage_id));
CREATE TABLE research_register.plan_criterion_reference (criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), referenced_criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), PRIMARY KEY(criterion_id,referenced_criterion_id));
CREATE TABLE research_register.plan_target (criterion_id VARCHAR PRIMARY KEY REFERENCES research_register.plan_criterion(criterion_id), target_year INTEGER, metric VARCHAR, value_as_reported VARCHAR, unit VARCHAR, operator_as_reported VARCHAR, reference_text VARCHAR, population VARCHAR);
CREATE TABLE research_register.plan_target_condition (criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), position INTEGER NOT NULL, condition_kind VARCHAR NOT NULL, metric VARCHAR, operator_as_reported VARCHAR, value_as_reported VARCHAR, unit VARCHAR, condition_text VARCHAR, PRIMARY KEY(criterion_id,position));
CREATE TABLE research_register.plan_target_series (criterion_id VARCHAR NOT NULL REFERENCES research_register.plan_criterion(criterion_id), series_label VARCHAR NOT NULL, target_year INTEGER NOT NULL, value_as_reported VARCHAR NOT NULL, unit VARCHAR, basis VARCHAR, PRIMARY KEY(criterion_id,series_label,target_year));
CREATE TABLE research_register.plan_trigger (trigger_id VARCHAR PRIMARY KEY, plan_id VARCHAR NOT NULL REFERENCES research_register.plan_extraction(plan_id), objective_id VARCHAR NOT NULL REFERENCES research_register.plan_objective(objective_id), condition_text VARCHAR NOT NULL, proposed_action VARCHAR NOT NULL);
CREATE TABLE research_register.plan_trigger_passage (trigger_id VARCHAR NOT NULL REFERENCES research_register.plan_trigger(trigger_id), passage_id INTEGER NOT NULL REFERENCES research_register.plan_passage(passage_id), PRIMARY KEY(trigger_id,passage_id));
CREATE TABLE research_register.plan_benefit (plan_id VARCHAR PRIMARY KEY REFERENCES research_register.plan_extraction(plan_id), classification VARCHAR NOT NULL, survey_commitment VARCHAR, external_data_opportunity VARCHAR);
CREATE TABLE research_register.plan_benefit_passage (plan_id VARCHAR NOT NULL REFERENCES research_register.plan_benefit(plan_id), passage_id INTEGER NOT NULL REFERENCES research_register.plan_passage(passage_id), PRIMARY KEY(plan_id,passage_id));
CREATE TABLE research_register.plan_reconciliation_issue (issue_id VARCHAR PRIMARY KEY, plan_id VARCHAR NOT NULL REFERENCES research_register.plan_extraction(plan_id), issue_text VARCHAR NOT NULL);
